            dp[0][0][0] = 0;
            dp[0][0][1] = dp[0][1][0] = dp[0][1][1] = INF;
            for(int k = 0; k < N; ++k) {
                dp[k + 1][0][0] = dp[k + 1][0][1] = dp[k + 1][1][0] = dp[k + 1][1][1] = INF;
                chmin(dp[k + 1][0][1], dp[k][0][0] + (S[k] != i));
                chmin(dp[k + 1][1][0], dp[k][0][0] + 1);
