int modmul(int a , int b , int mod){
    return (a % mod * b % mod) % mod;
}

int fastpow(int a, int b, int mod) {
    int ans = 1;
    a = a%mod;
    while (b > 0) {
        if (b & 1) {
            ans = modmul(ans,a,mod);
        }
        a = modmul(a,a,mod);
        b >>= 1;
    }
    return ans%mod;
}


int inv( int a , int p){
    return fastpow(a , p-2 , p);
}


